#include<iostream>
using namespace std;

int fact(int a){
    int b=1;
    if(a==0|| a==1){
        return b;
    }
    else{
        for(int i=2;i<=a;i++){
            b*=i;
        }
        return b;
    }
}

int main(){
    int num,sum=0;
    cout<<"Enter a number: ";
    cin>>num;
    int temp=num;
    while (temp>0){
        int dig=temp%10;
        sum+=fact(dig);
        temp=temp/10;
    }
    if(sum==num){
        cout<<"It's a strong number";
    }
    else{
        cout<<"It's not a strong number";
    }
    return 0;
}
