enum Operator {
    PLUS = 1,
    MINUS = 2,
    TIMES = 3,
    DIVIDE = 4,
    LEFT_PARENTHESIS = 5,
    RIGHT_PARENTHESIS = 6
};

// Stack to hold operators and operands
typedef struct {
    char operator;
    int operand;
} StackNode;

StackNode* stack = NULL;
int top = -1;

void push(int op, int val) {
    if (top == 5) {
