    StackNode* newNode = (StackNode*)malloc(sizeof(StackNode));
    newNode->operator = op;
    newNode->operand = val;
    stack[++top] = newNode;
}

int pop() {
    if (top == -1) {
        printf("Stack underflow\n");
        return -1;
    }
    int val = stack[top].operand;
    StackNode* temp = stack[--top];
    free(temp);
    return val;
}

char getOperator(int precedence) {
    switch (precedence) {
        case PLUS:
            return '+';
        case MINUS:
            return '-';
        case TIMES:
            return '*';
        case DIVIDE:
            return '/';
        default:
